/**
 * Authored review consequences. These lines are checked once by a human and are NOT generated by the model.
 * They contain no digits (so grounding never trips) and no verdict words (so a card can never leak a result).
 * Check them against the current Laws and the competition's playing conditions before you ship.
 */
export const REVIEW_TEXT = {
  wide: {
    ifStays: "The umpire's original call on the delivery stands.",
    ifChanges: "The call is reversed. A delivery first called wide becomes a legal ball, or the other way round. A wide adds an extra run and the ball is bowled again.",
  },
  no_ball: {
    ifStays: "The umpire's original call on the delivery stands.",
    ifChanges: "The call is reversed. A no-ball becomes a legal ball, or the other way round. A no-ball adds an extra run and the next delivery is a free hit.",
  },
  lbw: {
    ifStays: "The on-field decision stands and the batter's fate is unchanged.",
    ifChanges: "The on-field decision is reversed: either the batter is reprieved or a wicket falls.",
  },
  caught_behind: {
    ifStays: "The on-field decision stands and the batter's fate is unchanged.",
    ifChanges: "The on-field decision is reversed: either the batter is reprieved or a wicket falls.",
  },
  run_out: {
    ifStays: "The on-field decision stands and the batter's fate is unchanged.",
    ifChanges: "The on-field decision is reversed: either the batter is reprieved or a wicket falls, and any runs depend on the final ruling.",
  },
  unknown: {
    ifStays: "The on-field decision stands.",
    ifChanges: "The on-field decision is reversed.",
  },
};

/** Map whatever the data calls the review type onto a key of REVIEW_TEXT. */
export function reviewKey(kind) {
  const k = String(kind ?? "").toLowerCase();
  if (/wide/.test(k)) return "wide";
  if (/no[\s_-]?ball/.test(k)) return "no_ball";
  if (/lbw|leg before/.test(k)) return "lbw";
  if (/caught|behind|edge/.test(k)) return "caught_behind";
  if (/run[\s_-]?out/.test(k)) return "run_out";
  return "unknown";
}
export const reviewLines = (kind) => REVIEW_TEXT[reviewKey(kind)];

/** Words that would reveal how a review went. Checked on every field the model writes. */
export const VERDICT = /\b(not out|overturned|upheld|struck down|given out|is out|was out|has been given)\b/i;

export function assertNoSpoiler(card) {
  const text = [card.headline, ...(card.recap ?? []), card.why_it_matters, card.watch_next,
    card.review_explainer?.under_review ?? ""].join(" ");
  if (VERDICT.test(text)) throw new Error("Review card hints at the verdict");
}

/** Replace the model's if-stays / if-changes lines with the authored ones. */
export function applyReviewText(card, ctx) {
  if (!ctx.review) return card;
  const L = reviewLines(ctx.review.kind);
  return {
    ...card,
    review_explainer: {
      under_review: card.review_explainer?.under_review || `${ctx.review.by} have asked for a review.`,
      if_stays: L.ifStays, if_changes: L.ifChanges,
    },
  };
}
